declare(strict_types=1);require dirname(__DIR__).'/portal/bootstrap.php';require_once dirname(__DIR__).'/portal/visitor-intelligence.php';require_once dirname(__DIR__).'/portal/proposals-intake.php';if(!is_post()){http_response_code(405);exit('Method not allowed.');}if(!same_origin_request()){http_response_code(403);exit('Invalid request origin.');}verify_csrf();$action=trim((string)($_POST['action']??''));$token=strtolower(trim((string)($_POST['token']??'')));try{if(!proposals_schema_available())throw new RuntimeException('Proposal system unavailable.');if(rate_limit_exceeded('proposal_response',$token.'|'.request_ip(),8,3600))throw new RuntimeException('Too many response attempts. Please try again later.');if($action==='accept'){if(empty($_POST['acceptance_confirmed']))throw new RuntimeException('Confirm that you approve the proposal.');proposal_accept($token,(string)($_POST['accepted_name']??''));redirect('proposal.php?token='.rawurlencode($token).'&accepted=1');}if($action==='decline'){proposal_decline($token,(string)($_POST['declined_reason']??''));redirect('proposal.php?token='.rawurlencode($token).'&declined=1');}throw new RuntimeException('Unsupported proposal response.');}catch(Throwable $e){error_log('NMM proposal response failed: '.$e->getMessage());redirect('proposal.php?token='.rawurlencode($token).'&proposal_error='.rawurlencode($e->getMessage()));}
